function mostEvents(events: number[][]): number {
  const used = new Array(events.length).fill(false);
  let last = 0;
  for (const [, e] of events) last = Math.max(last, e);
  let count = 0;
  for (let day = 1; day <= last; day++) {
    let pick = -1;
    for (let i = 0; i < events.length; i++) {
      const [s, e] = events[i];
      if (!used[i] && s <= day && day <= e && (pick < 0 || e < events[pick][1])) pick = i;
    }
    if (pick >= 0) { used[pick] = true; count++; }
  }
  return count;
}

