class MinHeap {
  private a: number[] = [];
  get size() { return this.a.length; }
  peek() { return this.a[0]; }
  push(x: number) {
    const a = this.a; a.push(x);
    let i = a.length - 1;
    while (i > 0) {
      const p = (i - 1) >> 1;
      if (a[p] <= a[i]) break;
      [a[p], a[i]] = [a[i], a[p]]; i = p;
    }
  }
  pop(): number {
    const a = this.a, top = a[0], last = a.pop()!;
    if (a.length) {
      a[0] = last;
      let i = 0;
      for (;;) {
        const l = 2 * i + 1, r = l + 1;
        let m = i;
        if (l < a.length && a[l] < a[m]) m = l;
        if (r < a.length && a[r] < a[m]) m = r;
        if (m === i) break;
        [a[m], a[i]] = [a[i], a[m]]; i = m;
      }
    }
    return top;
  }
}

function mostEvents(events: number[][]): number {
  const ev = [...events].sort((x, y) => x[0] - y[0]);
  const heap = new MinHeap();
  let i = 0, day = 0, count = 0;
  while (i < ev.length || heap.size) {
    if (!heap.size) day = Math.max(day, ev[i][0]); // nothing open: jump ahead
    while (i < ev.length && ev[i][0] === day) heap.push(ev[i++][1]);
    while (heap.size && heap.peek() < day) heap.pop(); // already closed
    if (heap.size) { heap.pop(); count++; }
    day++;
  }
  return count;
}

