function mostEvents(events: number[][]): number {
  const ev = [...events].sort((x, y) => x[1] - y[1]);
  let last = 0;
  for (const [, e] of ev) last = Math.max(last, e);
  const next = Array.from({ length: last + 2 }, (_, d) => d); // next[d]: earliest free day >= d
  const find = (d: number): number => {
    while (next[d] !== d) { next[d] = next[next[d]]; d = next[d]; }
    return d;
  };
  let count = 0;
  for (const [s, e] of ev) {
    const d = find(s);
    if (d <= e) { count++; next[d] = d + 1; }
  }
  return count;
}

